protected void new()
{
    super();
}

/// <summary>
/// PaffH 24.03.25
/// </summary>
/// <param name = "_formRun">FormRun</param>
protected void InitFromFormRun(FormRun _formRun)
{
    super(_formRun);
    this.initControls();

    nDXPOPspecificDataManagementLine_DS = _formrun.dataHelper().FindDataSource(formDataSourceStr(NDXPOPspecificDataManagement, NDXPOPspecificDataManagementLine));
    nDXPOPspecificDataManagementHeader_DS = _formrun.dataHelper().FindDataSource(formDataSourceStr(NDXPOPspecificDataManagement, NDXPOPspecificDataManagementHeader));
    nDXPOPspecificDataManagementHeader = nDXPOPspecificDataManagementHeader_DS.cursor();
    nDXPOPspecificDataManagementParameters_DS = _formrun.dataHelper().FindDataSource(formDataSourceStr(NDXPOPspecificDataManagement, NDXPOPspecificDataManagementParameters));
    nDXPOPspecificDataManagementParameters = nDXPOPspecificDataManagementParameters_DS.cursor();

    this.editSet(false);

    FormGridControl gridControl = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormGridNDXPOPspecificDataManagementLine2)) as FormGridControl;
    if (gridControl)
    {
        gridControl.visibleRows(20);
    }
    gridControl = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormGridNDXPOPspecificDataManagementHistory_3)) as FormGridControl;
    if (gridControl)
    {
        gridControl.visibleRows(20);
    }
    gridControl = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormGridLinesTransfer)) as FormGridControl;
    if (gridControl)
    {
        gridControl.visibleRows(20);
    }

    FormTabPageControl tabPageControl = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormTabPageAdminBlockedUsers)) as FormTabPageControl;
    tabPageControl.visible(xUserInfo::isSysAdmin());
    tabPageControl = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormTabPageBlocked)) as FormTabPageControl;
    tabPageControl.visible(xUserInfo::isSysAdmin());
    tabPageControl = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormTabPageLinesTransfer)) as FormTabPageControl;
    tabPageControl.visible(xUserInfo::isSysAdmin() || NDXHelperSecurity::hasUserSecurityPrivilege('NDXPOPspecificDataManagementLineTransferEntityMaintain'));

    this.initializeNDXPOPspecificDataManagementHeaderUser();
}

/// <summary>
/// PaffH 21.03.25
/// </summary>
/// <param name = "_element">FormRun</param>
/// <returns>NDXPOPspecificDataManagementForm</returns>
public static NDXPOPspecificDataManagementForm NewFromForm(FormRun _element)
{
    NDXPOPspecificDataManagementForm form;
    form = new NDXPOPspecificDataManagementForm();
    form.InitFromFormRun(_element);
    return form;
}

