/// <summary>
/// PaffH 27.03.25
/// </summary>
public void refreshFormDesign()
{
    boolean editable = nDXPOPspecificDataManagementHeader.editable() == NoYes::Yes;
    FormTabPageControl tabPage = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormTabPageFilter)) as FormTabPageControl;
    tabPage.visible(editable);
    tabPage = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormTabPageFieldChanges)) as FormTabPageControl;
    tabPage.visible(editable);
    tabPage = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormTabPage01InventSiteOrderSetup)) as FormTabPageControl;
    tabPage.visible(editable);
    tabPage = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormTabPage02InventSiteOrderSetupDim)) as FormTabPageControl;
    tabPage.visible(editable);
    FormButtonGroupControl groupControl = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormButtonGroupNDXPOPspecificDataManagementLine)) as FormButtonGroupControl;
    groupControl.visible(editable);
    groupControl = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormButtonGroupPOPLineCRUD)) as FormButtonGroupControl;
    groupControl.visible(editable);

    FormButtonControl buttonControl = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormButtonUnlockBlocking)) as FormButtonControl;
    if (buttonControl)
    {
        buttonControl.visible(
            nDXPOPspecificDataManagementParameters.DataEntityTransferLinesBlocked == NoYes::Yes &&
            nDXPOPspecificDataManagementParameters.DataEntityTransferLinesBlockedByUser == curUserId());
    }

    if (editable)
    {
        this.inventItemOrderSetupChangeState();
        this.inventItemOrderSetupDimChangeState();
    }
    this.setEditModeOnDatasources(editable);
}

