/// <summary>
/// PaffH 25.03.25
/// </summary>
public void markLines()
{
    // PaffH 01.04 no mark
    if (true)       
    {
        return;
    }
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine = nDXPOPspecificDataManagementLine_DS.getFirst();
    while (nDXPOPspecificDataManagementLine)
    {
        nDXPOPspecificDataManagementLine_DS.markRecord(nDXPOPspecificDataManagementLine, nDXPOPspecificDataManagementLine.Marked == NoYes::Yes ? true : false);
        nDXPOPspecificDataManagementLine = nDXPOPspecificDataManagementLine_DS.getNext();
    }
}

/// <summary>
/// PaffH 22.04.25
/// </summary>
/// <param name = "_nDXPOPspecificDataManagementLine">NDXPOPspecificDataManagementLine</param>
public void markedModified(NDXPOPspecificDataManagementLine _nDXPOPspecificDataManagementLine)
{
    if (_nDXPOPspecificDataManagementLine.Marked != _nDXPOPspecificDataManagementLine.orig().Marked)
    {
        nDXPOPspecificDataManagementHeader.CounterMarked += (_nDXPOPspecificDataManagementLine.Marked == NoYes::Yes) ? 1 : -1;
    }
}

/// <summary>
/// PaffH 25.03.25
/// </summary>
/// <param name = "_q">Query</param>
public void markFromQuery(Query _q)
{
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine;
    Query q = new Query(_q);
    QueryBuildDataSource qbdsInventTable = SysQuery::findOrCreateDataSource(q, tableNum(InventTable));
    QueryBuildDataSource qbdsNDXPOPspecificDataManagementLine = SysQuery::findOrCreateDataSource(q, tableNum(NDXPOPspecificDataManagementLine), tableNum(InventTable));
    qbdsNDXPOPspecificDataManagementLine.relations(true);
    qbdsNDXPOPspecificDataManagementLine.joinMode(JoinMode::InnerJoin);
    qbdsNDXPOPspecificDataManagementLine.update(true);
    QueryRun qr = new QueryRun(q);
    ttsbegin;
    while (qr.next())
    {
        nDXPOPspecificDataManagementLine = qr.get(tableNum(NDXPOPspecificDataManagementLine));
        nDXPOPspecificDataManagementLine.Marked = NoYes::Yes;
        nDXPOPspecificDataManagementLine.update();
    }
    ttscommit;
    nDXPOPspecificDataManagementLine_DS.executeQuery();
    this.markLines();
}

/// <summary>
/// PaffH 25.03.25
/// </summary>
/// <param name = "_mark">NoYes (yes)</param>
public void markAll(NoYes _mark = NoYes::Yes)
{
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine = nDXPOPspecificDataManagementLine_DS.getFirst();
    ttsbegin;
    while (nDXPOPspecificDataManagementLine)
    {
        if (nDXPOPspecificDataManagementLine.Marked != _mark)
        {
            nDXPOPspecificDataManagementLine.Marked = _mark;
        }
        nDXPOPspecificDataManagementLine.update();
        nDXPOPspecificDataManagementLine = nDXPOPspecificDataManagementLine_DS.getNext();
    }
    ttscommit;
    nDXPOPspecificDataManagementHeader.refreshCounter();
    nDXPOPspecificDataManagementLine_DS.executeQuery();
    this.markLines();
}

/// <summary>
/// PaffH 24.03.25
/// </summary>
public void fillFromFilterValueItemId()
{
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine;
    InventTable inventTable;
    str filterValue = this.parmFilterValueItemId();
    FormGroupControl formGroupItemIdFilter = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormGroupItemIdFilter)) as FormGroupControl;
    FormGroupControl formGroupItemGroupIdFilter = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormGroupItemGroupIdFilter)) as FormGroupControl;
    FormRadioControl itemActionTypeReqGroupId = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormRadioButtonItemActionTypeReqGroupId)) as FormRadioControl;

    boolean formGroupItemIdFilterActive = formGroupItemIdFilter.optionValue();
    boolean formGroupItemGroupIdFilterActive = formGroupItemGroupIdFilter.optionValue();
    utcdatetime updatedUTC = DateTimeUtil::utcNow();

    NDXItemActionType itemActionTypeReqGroupIdValue = itemActionTypeReqGroupId.selection();
    switch (itemActionTypeReqGroupIdValue)
    {
        case NDXItemActionType::InsertExcl:
            break;
        case NDXItemActionType::InsertIncl:
            break;
        case NDXItemActionType::Mark:
            break;
    }

    Query q = new Query();
    QueryBuildDataSource qbdsInventTable = q.addDataSource(tableNum(InventTable));
    if (formGroupItemIdFilter && filterValue)
    {
        qbdsInventTable.addRange(fieldNum(InventTable, ItemId)).value(SysQuery::valueLike(filterValue));
    }
    FormStringControl filterControlitemGroupId = thisFormRun.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormStringItemGroupIdFilter)) as FormStringControl;
    if (formGroupItemGroupIdFilterActive && filterControlitemGroupId.valueStr())
    {
        QueryBuildDataSource qbdsInventItemGroupItem = qbdsInventTable.addDataSource(tableNum(InventItemGroupItem));
        qbdsInventItemGroupItem.joinMode(JoinMode::InnerJoin);
        qbdsInventItemGroupItem.relations(true);
        qbdsInventItemGroupItem.addRange(fieldNum(InventItemGroupItem, ItemGroupId)).value(queryValue(filterControlitemGroupId.valueStr()));
    }

    QueryRun qr = new QueryRun(q);
    if (itemActionTypeReqGroupIdValue == NDXItemActionType::Mark)
    {
        this.markFromQuery(q);
        return;
    }

    while (qr.next())
    {
        inventTable = qr.get(tableNum(InventTable));

        nDXPOPspecificDataManagementLine.clear();
        nDXPOPspecificDataManagementLine.initValue();
        nDXPOPspecificDataManagementLine.initFromHeaderTable(nDXPOPspecificDataManagementHeader);
        nDXPOPspecificDataManagementLine.initFromInventTable(inventTable);
        nDXPOPspecificDataManagementLine = NDXPOPspecificDataManagementLine::findOrCreate(nDXPOPspecificDataManagementLine, false);
        if (nDXPOPspecificDataManagementLine.RecId != 0)
        {
            nDXPOPspecificDataManagementLine.fillChangeableFieldsInventTable(inventTable);
        }
        nDXPOPspecificDataManagementLine.UpdatedUTC = updatedUTC;
        ttsbegin;
        nDXPOPspecificDataManagementLine.write();
        ttscommit;
    }
    if (itemActionTypeReqGroupIdValue == NDXItemActionType::InsertExcl)
    {
        delete_from nDXPOPspecificDataManagementLine
            where nDXPOPspecificDataManagementLine.NDXPOPspecificDataManagementHeader == nDXPOPspecificDataManagementHeader.RecId
            && nDXPOPspecificDataManagementLine.Changed == NoYes::No
            && nDXPOPspecificDataManagementLine.UpdatedUTC != updatedUTC;
    }
    nDXPOPspecificDataManagementLine_DS.executeQuery();
    nDXPOPspecificDataManagementHeader.refreshCounter();
}

/// <summary>
/// PaffH 24.03.25
/// </summary>
public void saveChangeFields()
{
    str infoTxt = strFmt("@NDX:NDXPOPSaveChangedFieldsStart", NDXHelperCommon::seconds2Str());
    boolean changeFields;
    real realValue;
    Counter counterRec = 0;
    Counter counterChanged = 0;
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine;
    nDXPOPspecificDataManagementLine.selectForUpdate(true);
    nDXPOPspecificDataManagementLine = nDXPOPspecificDataManagementLine_DS.getFirst();

    ttsbegin;
    while (nDXPOPspecificDataManagementLine)
    {
        ++counterRec;
        changeFields = nDXPOPspecificDataManagementHeader.MarkedChange == NoYes::No || nDXPOPspecificDataManagementLine.Marked == NoYes::Yes;
        if (changeFields)
        {
            ++counterChanged;
            if (nDXPOPspecificDataManagementHeader.ActiveReqGroupId)
            {
                nDXPOPspecificDataManagementLine.ReqGroupIdNew = changeValueReqGroupId.valueStr();
            }

            // Standardauftragseinstellungen
            if (nDXPOPspecificDataManagementHeader.InventItemOrderSetupEdit)
            {
                if (nDXPOPspecificDataManagementHeader.InventItemOrderSetupPurchEdit)
                {
                    if (nDXPOPspecificDataManagementHeader.ActivePurchQtyMultiples01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemPurchSetupQtyMultiplesDefaultNew = qtyMultiplesPurch01.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActivePurchQtyLowest01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemPurchSetupQtyLowestDefaultNew = qtyLowestPurch01.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActivePurchQtyHighest01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemPurchSetupQtyHighestDefaultNew = qtyHighestPurch01.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActivePurchQtyStandard01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemPurchSetupQtyStandardDefaultNew = qtyStandardPurch01.realValue();
                    }
                }
                if (nDXPOPspecificDataManagementHeader.InventItemOrderSetupInventEdit)
                {
                    if (nDXPOPspecificDataManagementHeader.ActiveInventQtyMultiples01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemInventSetupQtyMultiplesDefaultNew = qtyMultiplesInvent01.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveInventQtyLowest01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemInventSetupQtyLowestDefaultNew = qtyLowestInvent01.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveInventQtyHighest01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemInventSetupQtyHighestDefaultNew = qtyHighestInvent01.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveInventQtyStandard01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemInventSetupQtyStandardDefaultNew = qtyStandardInvent01.realValue();
                    }
                }

                if (nDXPOPspecificDataManagementHeader.InventItemOrderSetupSalesEdit)
                {
                    if (nDXPOPspecificDataManagementHeader.ActiveSalesQtyMultiples01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemSalesSetupQtyMultiplesDefaultNew = qtyMultiplesSales01.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveSalesQtyLowest01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemSalesSetupQtyLowestDefaultNew = qtyLowestSales01.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveSalesQtyHighest01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemSalesSetupQtyHighestDefaultNew = qtyHighestSales01.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveSalesQtyStandard01)
                    {
                        nDXPOPspecificDataManagementLine.InventItemSalesSetupQtyStandardDefaultNew = qtyStandardSales01.realValue();
                    }
                }
            }

            // standortspezifische Auftragseinstellungen
            if (nDXPOPspecificDataManagementHeader.InventItemOrderSetupDimEdit)
            {
                if (nDXPOPspecificDataManagementHeader.InventItemOrderSetupDimPurchEdit)
                {
                    if (nDXPOPspecificDataManagementHeader.ActivePurchQtyMultiples02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemPurchSetupQtyMultiplesNew = qtyMultiplesPurch02.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActivePurchQtyLowest02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemPurchSetupQtyLowestNew = qtyLowestPurch02.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActivePurchQtyHighest02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemPurchSetupQtyHighestNew = qtyHighestPurch02.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActivePurchQtyStandard02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemPurchSetupQtyStandardNew = qtyStandardPurch02.realValue();
                    }
                }
                if (nDXPOPspecificDataManagementHeader.InventItemOrderSetupDimInventEdit)
                {
                    if (nDXPOPspecificDataManagementHeader.ActiveInventQtyMultiples02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemInventSetupQtyMultiplesNew = qtyMultiplesInvent02.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveInventQtyLowest02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemInventSetupQtyLowestNew = qtyLowestInvent02.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveInventQtyHighest02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemInventSetupQtyHighestNew = qtyHighestInvent02.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveInventQtyStandard02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemInventSetupQtyStandardNew = qtyStandardInvent02.realValue();
                    }
                }

                if (nDXPOPspecificDataManagementHeader.InventItemOrderSetupDimSalesEdit)
                {
                    if (nDXPOPspecificDataManagementHeader.ActiveSalesQtyMultiples02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemSalesSetupQtyMultiplesNew = qtyMultiplesSales02.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveSalesQtyLowest02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemSalesSetupQtyLowestNew = qtyLowestSales02.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveSalesQtyHighest02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemSalesSetupQtyHighestNew = qtyHighestSales02.realValue();
                    }
                    if (nDXPOPspecificDataManagementHeader.ActiveSalesQtyStandard02)
                    {
                        nDXPOPspecificDataManagementLine.InventItemSalesSetupQtyStandardNew = qtyStandardSales02.realValue();
                    }
                }
            }
            nDXPOPspecificDataManagementLine.update();
        }
        nDXPOPspecificDataManagementLine = nDXPOPspecificDataManagementLine_DS.getNext();
    }
    ttscommit;
    nDXPOPspecificDataManagementLine_DS.executeQuery();
    this.markLines();
    infoTxt += strFmt("@NDX:NDXPOPSaveChangedFieldsEnd", NDXHelperCommon::seconds2Str(), counterRec, counterChanged);
    Info(infoTxt);
}

/// <summary>
/// PaffH 25.03.25
/// save changes to inventtable and specific tables
/// </summary>
/// <param name = "_checkOnly">boolean (false)</param>
public void changeFields()
{
    str infoTxt = strFmt("@NDX:NDXPOPChangeFieldStart", NDXHelperCommon::seconds2Str());
    NDXPOPValidateWriteCheck nDXPOPValidateWriteCheck;
    utcdatetime lastChecked = DateTimeUtil::utcNow();
    this.refreshLines();
    NDXCounter counterRec = 0;
    NDXCounter counterUpdate = 0;
    NDXCounter counterNoChanges = 0;
    NDXCounter counterWithError = 0;
    boolean changeValidInventTable;
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine;
    nDXPOPspecificDataManagementLine.selectForUpdate(true);
    nDXPOPspecificDataManagementLine = nDXPOPspecificDataManagementLine_DS.getFirst();
    ttsbegin;
    while (nDXPOPspecificDataManagementLine)
    {
        if (nDXPOPspecificDataManagementHeader.MarkedChange == NoYes::No || nDXPOPspecificDataManagementLine.Marked == NoYes::Yes)
        {
            ++counterRec;

            nDXPOPspecificDataManagementLine.POPValidateWriteCheck = nDXPOPspecificDataManagementLine.validateChanges(false);
            nDXPOPspecificDataManagementLine.LastValidateWriteCheck = lastChecked;
            if (nDXPOPspecificDataManagementLine.POPValidateWriteCheck == NDXPOPValidateWriteCheck::WriteCheckOK)
            {
                nDXPOPspecificDataManagementLine.Changed = NoYes::Yes;
                nDXPOPspecificDataManagementLine.POPValidateWriteCheck = nDXPOPspecificDataManagementLine.validateChanges(true);
            }
            nDXPOPspecificDataManagementLine.update();
            switch (nDXPOPspecificDataManagementLine.POPValidateWriteCheck)
            {
                case NDXPOPValidateWriteCheck::NoFieldsChanged:
                    ++counterNoChanges;
                    break;
                case NDXPOPValidateWriteCheck::WriteCheckOK:
                    ++counterUpdate;
                    break;
                case NDXPOPValidateWriteCheck::WriteCheckWithError:
                    ++counterWithError;
                    break;
            }
        }
        nDXPOPspecificDataManagementLine = nDXPOPspecificDataManagementLine_DS.getNext();
    }
    ttscommit;
    nDXPOPspecificDataManagementLine_DS.executeQuery();
    this.markLines();
    if (counterWithError)
    {
        error(strFmt("@NDXBase:NDXRecWithErrorNoChangeChecked", counterWithError, counterUpdate, counterNoChanges, counterRec));
    }
    else if (counterUpdate < counterRec)
    {
        warning(strFmt("@NDXBase:NDXRecWithErrorNoChangeChecked", counterWithError, counterUpdate, counterNoChanges, counterRec));
    }
    else
    {
        Info(strFmt("@NDXBase:NDXChangedRecords2", counterUpdate));
    }
}

/// <summary>
/// PaffH 24.03.25
/// last modified: PaffH 09.04.25
/// </summary>
public void refreshLines()
{
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine;
    InventTable inventTable;
    ttsbegin;
    while select forupdate nDXPOPspecificDataManagementLine
        where nDXPOPspecificDataManagementLine.NDXPOPspecificDataManagementHeader == nDXPOPspecificDataManagementHeader.RecId
        && (nDXPOPspecificDataManagementHeader.MarkedChange == NoYes::No || nDXPOPspecificDataManagementLine.Marked == NoYes::Yes)
        join inventTable
        where inventTable.RecId == nDXPOPspecificDataManagementLine.InventTable
    {
        nDXPOPspecificDataManagementLine.fillChangeableFieldsInventTable(inventTable);
        nDXPOPspecificDataManagementLine.update();
    }
    ttscommit;
    nDXPOPspecificDataManagementLine_DS.executeQuery();
    nDXPOPspecificDataManagementHeader.refreshCounter();
}

