public void setEditModeOnDatasources(boolean _allow = true)
{
    nDXPOPspecificDataManagementLine_DS.allowDelete(_allow);
    nDXPOPspecificDataManagementLine_DS.allowEdit(_allow);
    nDXPOPspecificDataManagementHeader_DS.allowDelete(_allow);
    nDXPOPspecificDataManagementHeader_DS.allowEdit(_allow);
}

/// <summary>
/// PaffH 29.03.25
/// </summary>
/// <param name = "_allow">boolean (true)</param>
public void editSet(boolean _allow = true)
{
    //NDXPOPspecificDataManagementHeader nDXPOPspecificDataManagementHeader = nDXPOPspecificDataManagementHeader_DS.cursor();
    nDXPOPspecificDataManagementHeader.reread();
    if (_allow && nDXPOPspecificDataManagementHeader.editableSet() == NoYes::No)
    {
        _allow = false;
    }
    if (_allow && nDXPOPspecificDataManagementHeader.blocked() == NoYes::Yes)
    {
        warning(strFmt("@NDX:NDXPOPSetBlockedInfo", nDXPOPspecificDataManagementHeader.BlockedByUser, nDXPOPspecificDataManagementHeader.BlockedSince));
        return;
    }
    this.setEditModeOnDatasources(_allow);
    if (nDXPOPspecificDataManagementHeader && nDXPOPspecificDataManagementHeader.editableSet() == NoYes::Yes)
    {
        boolean lUpdate = false;
        if (_allow)
        {
            nDXPOPspecificDataManagementHeader.BlockedByUser = curUserId();
            nDXPOPspecificDataManagementHeader.modifiedField(fieldNum(NDXPOPspecificDataManagementHeader, BlockedByUser));
            lUpdate = true;
        }
        else
        {
            if (nDXPOPspecificDataManagementHeader.BlockedByUser != '' 
                && nDXPOPspecificDataManagementHeader.BlockedSince != utcDateTimeNull())
            {
                nDXPOPspecificDataManagementHeader.BlockedByUser = '';
                nDXPOPspecificDataManagementHeader.modifiedField(fieldNum(NDXPOPspecificDataManagementHeader, BlockedByUser));
                lUpdate = true;
            }
        }
        if (lUpdate)
        {
            nDXPOPspecificDataManagementHeader.selectForUpdate(true);
            nDXPOPspecificDataManagementHeader.update();
        }
    }
    this.refreshFormDesign();
}

/// <summary>
/// PaffH 31.03.25
/// </summary>
public void initializeNDXPOPspecificDataManagementHeaderUser()
{
    FormDataSource fds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXPOPspecificDataManagement, NDXPOPspecificDataManagementHeaderUser));
    NDXPOPspecificDataManagementHeaderUser nDXPOPspecificDataManagementHeaderUser = fds.cursor();
    NDXPOPspecificDataManagementHeaderUser nDXPOPspecificDataManagementHeaderUserLocal;
    nDXPOPspecificDataManagementHeader nDXPOPspecificDataManagementHeaderLocal;
    while select * from nDXPOPspecificDataManagementHeaderLocal
    {
        nDXPOPspecificDataManagementHeaderUserLocal.clear();
        nDXPOPspecificDataManagementHeaderUserLocal.NDXPOPspecificDataManagementHeader = nDXPOPspecificDataManagementHeaderLocal.RecId;
        nDXPOPspecificDataManagementHeaderUserLocal.Blocked = NDXPOPspecificDataManagementHeaderLocal.blocked();
        nDXPOPspecificDataManagementHeaderUserLocal.insert();
    }
    nDXPOPspecificDataManagementHeaderUser.setTmpData(nDXPOPspecificDataManagementHeaderUserLocal);
}

/// <summary>
/// PaffH 31.03.25
/// </summary>
public void validateChanges()
{
    Counter counterRec = 0;
    Counter counterChecked = 0;
    Counter counterNoFieldsChanged = 0;
    Counter counterWriteCheckOK = 0;
    Counter counterWriteCheckWithError = 0;
    str infoTxt = strFmt("@NDX:NDXPOPValidateChangesStart", NDXHelperCommon::seconds2Str());
    this.refreshLines();
    utcdatetime lastChecked = DateTimeUtil::utcNow();
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine = nDXPOPspecificDataManagementLine_DS.getFirst();

    ttsbegin;
    nDXPOPspecificDataManagementLine.selectForUpdate(true);
    while (nDXPOPspecificDataManagementLine)
    {
        ++counterRec;
        if (nDXPOPspecificDataManagementHeader.MarkedChange == NoYes::No || nDXPOPspecificDataManagementLine.Marked == NoYes::Yes)
        {
            ++counterChecked;
            nDXPOPspecificDataManagementLine.POPValidateWriteCheck = nDXPOPspecificDataManagementLine.validateChanges();
            nDXPOPspecificDataManagementLine.LastValidateWriteCheck = lastChecked;
            nDXPOPspecificDataManagementLine.update();
            switch (nDXPOPspecificDataManagementLine.POPValidateWriteCheck)
            {
                case NDXPOPValidateWriteCheck::NoFieldsChanged:
                    ++counterNoFieldsChanged;
                    break;
                case NDXPOPValidateWriteCheck::WriteCheckOK:
                    ++counterWriteCheckOK;
                    break;
                case NDXPOPValidateWriteCheck::WriteCheckWithError:
                    ++counterWriteCheckWithError;
                    break;
            }
        }
        nDXPOPspecificDataManagementLine = nDXPOPspecificDataManagementLine_DS.getNext();
    }
    ttscommit;
    nDXPOPspecificDataManagementLine_DS.executeQuery();
    infoTxt += strFmt("@NDX:NDXPOPValidateChangesEnd", NDXHelperCommon::seconds2Str(), counterRec, counterChecked, counterWriteCheckWithError, counterWriteCheckOK, counterNoFieldsChanged);
    if (counterWriteCheckWithError)
    {
        warning(infoTxt);
    }
    else
    {
        Info(infoTxt);
    }
}

