                        {
                            nDXPOPspecificDataManagementHeader.ActiveSalesQtyMultiples01 = false;
                        }
                        if (nDXPOPspecificDataManagementHeader.ActiveSalesQtyStandard01)
                        {
                            nDXPOPspecificDataManagementHeader.ActiveSalesQtyStandard01 = false;
                        }
                    }
                }
            }
        }
    }
    nDXPOPspecificDataManagementHeader_ds.write();
}

/// <summary>
/// PaffH 22.04.25
/// transfer lines (NDXPOPspecificDataManagementLineTransferEntity)
/// </summary>
public void initializeLinesTransfer()
{
    //NDXPOPspecificDataManagementParameters nDXPOPspecificDataManagementParameters = NDXPOPspecificDataManagementParameters::find(true);
    if (nDXPOPspecificDataManagementParameters.DataEntityTransferLinesBlocked == NoYes::Yes &&
        nDXPOPspecificDataManagementParameters.DataEntityTransferLinesBlockedByUser != curUserId())
    {
        warning(strFmt("@NDXBase:NDXOptionUse1Person",
            NDXHelperCommon::utcNowUser(nDXPOPspecificDataManagementParameters.DataEntityTransferLinesBlockedSince), 
            nDXPOPspecificDataManagementParameters.DataEntityTransferLinesBlockedByUser));
        return;
    }
    nDXPOPspecificDataManagementParameters.DataEntityTransferLinesBlocked = NoYes::Yes;
    nDXPOPspecificDataManagementParameters.DataEntityTransferLinesBlockedByUser = curUserId();
    nDXPOPspecificDataManagementParameters.DataEntityTransferLinesBlockedSince = DateTimeUtil::utcNow();
    nDXPOPspecificDataManagementParameters.update();

    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLineLocal;
    NDXPOPspecificDataManagementLineTransfer nDXPOPspecificDataManagementLineTransferLocal;
    delete_from nDXPOPspecificDataManagementLineTransferLocal;
    while select nDXPOPspecificDataManagementLineLocal
        where nDXPOPspecificDataManagementLineLocal.NDXPOPspecificDataManagementHeader == nDXPOPspecificDataManagementHeader.RecId
    {
        nDXPOPspecificDataManagementLineTransferLocal.clear();
        nDXPOPspecificDataManagementLineTransferLocal.initValue();
        nDXPOPspecificDataManagementLineTransferLocal.initFromHeaderTable(nDXPOPspecificDataManagementHeader);
        nDXPOPspecificDataManagementLineTransferLocal.initFromInventTable(InventTable::findByRecId(nDXPOPspecificDataManagementLineLocal.InventTable));
        nDXPOPspecificDataManagementLineTransferLocal.initFromNDXPOPspecificDataManagementLine(nDXPOPspecificDataManagementLineLocal);
        nDXPOPspecificDataManagementLineTransferLocal.insert();
    }
    FormDataSource nDXPOPspecificDataManagementLineTransfer_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXPOPspecificDataManagement, NDXPOPspecificDataManagementLineTransfer));
    nDXPOPspecificDataManagementLineTransfer_DS.executeQuery();
}

/// <summary>
/// PaffH 22.04.25
/// initialize from dataentity transfer
/// </summary>
public void initializeFromLinesTransfer()
{
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLineLocal;
    NDXPOPspecificDataManagementLineTransfer nDXPOPspecificDataManagementLineTransferLocal;
    ttsbegin;
    while select nDXPOPspecificDataManagementLineTransferLocal
        where nDXPOPspecificDataManagementLineTransferLocal.NDXPOPspecificDataManagementHeader == nDXPOPspecificDataManagementHeader.RecId
        join forupdate nDXPOPspecificDataManagementLineLocal
        where nDXPOPspecificDataManagementLineLocal.NDXPOPspecificDataManagementHeader == nDXPOPspecificDataManagementLineTransferLocal.NDXPOPspecificDataManagementHeader
        && nDXPOPspecificDataManagementLineLocal.InventTable == nDXPOPspecificDataManagementLineTransferLocal.InventTable
    {
        nDXPOPspecificDataManagementLineLocal.initFromNDXPOPspecificDataManagementLineTransfer(nDXPOPspecificDataManagementLineTransferLocal);
        nDXPOPspecificDataManagementLineLocal.update();
    }
    ttscommit;
    nDXPOPspecificDataManagementLine_ds.executeQuery();
    //NDXPOPspecificDataManagementParameters nDXPOPspecificDataManagementParameters = NDXPOPspecificDataManagementParameters::find(true);
    nDXPOPspecificDataManagementParameters.DataEntityTransferLinesBlocked = NoYes::No;
    nDXPOPspecificDataManagementParameters.update();
}

