/// <summary>
/// PaffH 24.04.25
/// </summary>
public void filterMarkedLines()
{
    QueryBuildDataSource qbds = nDXPOPspecificDataManagementLine_DS.query().dataSourceTable(tableNum(NDXPOPspecificDataManagementLine));
    QueryBuildRange qbr = SysQuery::findOrCreateRange(qbds, fieldNum(NDXPOPspecificDataManagementLine, Marked));
    if (nDXPOPspecificDataManagementHeader.FilterMarked == NoYes::Yes)
    {
        qbr.value(queryValue(NoYes::Yes));
    }
    else
    {
        qbr.value(SysQuery::valueUnlimited());
    }
    nDXPOPspecificDataManagementLine_DS.executeQuery();
}
